{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.span_name, count(*) n, sum(CASE WHEN c.duration>500000000 THEN 1 ELSE 0 END) slow_n, round(avg(c.duration)/1e6,1) caller_client_ms, round(avg(p.duration)/1e6,1) callee_server_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id WHERE c.service_name='ts-seat-service' AND c.attr_span_kind='Client' AND p.service_name='ts-order-other-service' GROUP BY 1",
          "claim": "Seat's POST to order-other /tickets: 259 of 260 client spans exceed 500ms (avg ~1346ms), while callee server spans stay ~17ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, p.service_name callee, p.span_name, count(*) n, round(avg(c.duration)/1e6,1) caller_ms, round(avg(p.duration)/1e6,1) callee_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id WHERE c.service_name='ts-seat-service' AND c.attr_span_kind='Client' GROUP BY 1,2,3 ORDER BY 2,3",
          "claim": "Seat's other outgoing calls (config, order) stay near normal; only the order-other tickets path shows the large gap."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_source, attr_destination, round(avg(value),1) avg_v FROM abnormal_metrics_sum WHERE metric IN ('hubble_drop_total','hubble_tcp_flags_total') AND attr_source LIKE '%seat-service%' AND attr_destination LIKE '%order-other%' GROUP BY 1,2,3",
          "claim": "Per-connection seat to order-other network counters show no drops or retransmit-type anomaly, so the delay is at the HTTP layer rather than on the wire."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, p.service_name callee, count(*) n, round(avg(c.duration)/1e6,1) caller_ms, round(avg(p.duration)/1e6,1) callee_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id WHERE c.service_name='ts-travel2-service' AND p.service_name='ts-seat-service' AND p.attr_span_kind='Server' AND c.attr_span_kind='Client' GROUP BY 1,2",
          "claim": "travel2 calls to seat take about 1413ms versus 18ms in normal; the seat delay propagates to travel2."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, p.service_name callee, count(*) n, round(avg(c.duration)/1e6,1) caller_ms, round(avg(p.duration)/1e6,1) callee_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id WHERE c.service_name='ts-route-plan-service' AND p.service_name='ts-travel2-service' AND p.attr_span_kind='Server' AND c.attr_span_kind='Client' GROUP BY 1,2",
          "claim": "route-plan calls to travel2 rise to about 1423ms from 48ms, with the callee's server time matching."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, p.service_name callee, count(*) n, round(avg(c.duration)/1e6,1) caller_ms, round(avg(p.duration)/1e6,1) callee_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id WHERE c.service_name='ts-travel-plan-service' AND p.service_name='ts-route-plan-service' AND p.attr_span_kind='Server' AND c.attr_span_kind='Client' GROUP BY 1,2",
          "claim": "travel-plan calls to route-plan take about 3170ms versus 256ms in normal."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.service_name svc, s.span_name, count(*) n, round(avg(s.duration)/1e6,1) avg_ms FROM abnormal_traces s JOIN abnormal_traces r ON s.trace_id=r.trace_id AND (r.parent_span_id IS NULL OR r.parent_span_id='') WHERE s.service_name IN ('ts-route-plan-service','ts-travel2-service') AND s.attr_span_kind='Server' AND r.span_name LIKE '%travelPlan%' GROUP BY 1,2",
          "claim": "User-facing travelPlan requests from ui-dashboard hit route-plan server spans averaging 2800-3100ms, reflecting the slowed chain."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, p.service_name callee, count(*) n, round(avg(c.duration)/1e6,1) caller_ms, round(avg(p.duration)/1e6,1) callee_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id WHERE c.service_name='ts-preserve-service' AND p.service_name='ts-seat-service' AND p.attr_span_kind='Server' AND c.attr_span_kind='Client' GROUP BY 1,2",
          "claim": "preserve calls to seat rise to about 210ms from 15ms as seat's server stalls on the order-other calls."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.service_name, count(*) n, round(avg(s.duration)/1e6,1) avg_ms FROM abnormal_traces s JOIN abnormal_traces r ON s.trace_id=r.trace_id AND (r.parent_span_id IS NULL OR r.parent_span_id='') WHERE s.service_name='ts-preserve-service' AND s.attr_span_kind='Server' AND r.span_name LIKE '%preserve%' GROUP BY 1",
          "claim": "User preserve requests routed via ui-dashboard see preserve-service server latency around 509ms, versus about 226ms in normal traffic."
        }
      ]
    }
  ]
}
